import math
def priority(task, state, q_thresh=0.5, k=0.5, m=3.0):
    # Switch behavior based on queue congestion.
    # Under light load, use stage-weighted slack; under heavy load, use ATC-like urgency.
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    stage_cost = {'variant_calling': 5.0, 'sv_calling': 3.0, 'alignment': 1.0}.get(task.task_type, 1.0)
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, 1e-6)
    if load < q_thresh:
        # Light load: prioritize by stage cost and tightness of slack.
        return stage_cost * tier / max(slack, 1e-6)
    else:
        # Heavy load: ATC-like with stage/tier scaling.
        base = (stage_cost * tier * task.weight) / max(task.estimated_runtime, 1e-6)
        return base * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

