```python
def priority(task, state, k=1.0, stage_vc=3.0, stage_sv=2.0, stage_aln=1.0, tier_prem=2.0, tier_std=1.0, pressure_w=0.5):
    import math
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    stage = stage_aln
    if task.task_type == 'variant_calling':
        stage = stage_vc
    elif task.task_type == 'sv_calling':
        stage = stage_sv
    tier = tier_prem if task.tenant == 'premium' else tier_std
    pressure = state.queue_work / max(state.capacity, 1e-6)
    urgency = stage / max(slack, 1e-6) if slack > 0 else stage * (1.0 + abs(slack) / est)
    return tier * urgency / (1.0 + pressure_w * pressure)
```

