def priority(task, state, eps=1e-6, q_hi=0.5, q_lo=0.2, k_hi=0.3, k_lo=1.0):
    # Queue-adaptive ATC: when the queue is heavily loaded relative to
    # capacity, sharpen urgency (small k) to protect due dates; when lightly
    # loaded, relax to let long jobs through and reduce average wait.
    load = state.queue_work / max(state.capacity, eps)
    if load >= q_hi:
        k = k_hi
    elif load <= q_lo:
        k = k_lo
    else:
        k = k_lo + (k_hi - k_lo) * (load - q_lo) / max(q_hi - q_lo, eps)
    type_cost = {'variant_calling': 5.0, 'sv_calling': 3.0, 'alignment': 1.0}.get(task.task_type, 1.0)
    tier = 2.0 if task.tenant == 'premium' else 1.0
    est = max(task.estimated_runtime, eps)
    slack = max(0.0, task.due - est - state.now)
    return tier * type_cost / est * math.exp(-slack / (k * max(state.mean_est, eps)))

